import 'package:flutter/material.dart';import 'package:zan/Features/Splash/Pages/splash_screen.dart';import '../../Features/Authentication/presentation/pages/authentication_screen.dart';import 'route_constants.dart';class AppRoutes {  static Route<dynamic> generateRoute(RouteSettings settings) {    switch (settings.name) {      case RouteNames.splash:        return MaterialPageRoute(builder: (_) => const SplashScreen());      case RouteNames.home:      // return MaterialPageRoute(builder: (_) => const HomePage());      case RouteNames.start:        return MaterialPageRoute(builder: (_) => const AuthenticationScreen());      default:        return MaterialPageRoute(          builder: (_) => Scaffold(            body: Center(              child: Text('No route defined for ${settings.name}'),            ),          ),        );    }  }}